create table if not exists platform_users (id uuid primary key, email text unique not null, password_hash text not null, created_at timestamptz not null default now());
create table if not exists booking_businesses (id uuid primary key, user_id uuid unique not null references platform_users(id) on delete cascade, name text not null, slug text unique not null, timezone text not null default 'Africa/Lagos', whatsapp text, created_at timestamptz not null default now());
create table if not exists platform_sessions (token_hash text primary key, user_id uuid not null references platform_users(id) on delete cascade, expires_at timestamptz not null);
create table if not exists booking_services (id uuid primary key, business_id uuid not null references booking_businesses(id) on delete cascade, name text not null, description text not null default '', price_ngn integer not null check (price_ngn >= 0), duration_minutes integer not null check (duration_minutes > 0), buffer_minutes integer not null default 0 check (buffer_minutes >= 0), active boolean not null default true);
create table if not exists booking_customers (id uuid primary key, business_id uuid not null references booking_businesses(id) on delete cascade, name text not null, phone text not null, email text, notes text not null default '');
create table if not exists booking_appointments (id uuid primary key, business_id uuid not null references booking_businesses(id) on delete cascade, service_id uuid not null references booking_services(id), customer_id uuid not null references booking_customers(id), starts_at timestamptz not null, status text not null check (status in ('Pending','Confirmed','Completed','Cancelled','No-show')), notes text not null default '', created_at timestamptz not null default now());
create index if not exists booking_appointments_business_start on booking_appointments(business_id, starts_at);
alter table booking_appointments add column if not exists reference text unique;
